"""Self-contained browser report for measured pretrained head interventions."""
import json
from pathlib import Path
import numpy as np
from .pretrained import read


def render(output, spec_dir):
    output, spec_dir = Path(output), Path(spec_dir)
    with np.load(output / 'measurements.npz', allow_pickle=False) as data:
        payload = {'summary': read(output / 'summary.json'), 'examples': read(output / 'examples.json'),
                   'provenance': read(output / 'provenance.json'), 'sources': read(spec_dir / 'sources.json'),
                   'protocol': read(spec_dir / 'protocol.json'),
                   'attention': np.round(data['attention'].astype(float), 6).tolist(),
                   'intact': data['intact'][:2].tolist(),
                   'zero': data['zero'][:, :, :2].tolist(), 'mean': data['mean'][:, :, :2].tolist()}
    encoded = json.dumps(payload, ensure_ascii=True, separators=(',', ':'), allow_nan=False).replace('<', '\\u003c')
    (output / 'report.html').write_text(TEMPLATE.replace('__DATA__', encoded))


TEMPLATE = r'''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Pythia-14M · Attention Intervention Lab</title>
<style>
:root{font:16px system-ui,sans-serif;color:#172c3b;background:#f2f5f7}body{max-width:1180px;margin:auto;padding:24px}h1{font-size:2.3rem;margin:10px 0}h2{margin-top:0}p{line-height:1.6;max-width:95ch}.eyebrow{color:#166d76;letter-spacing:.12em;font-size:.8rem;font-weight:700}.card{background:white;border:1px solid #dbe3e8;border-radius:12px;padding:22px;margin:20px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.metrics{display:flex;gap:20px;flex-wrap:wrap}.metric{padding:14px 20px;background:#e8f3f3;border-radius:8px}.metric strong{display:block;font-size:1.5rem}.controls{display:flex;gap:16px;flex-wrap:wrap;margin:16px 0}label{display:flex;flex-direction:column;gap:5px}select,button,input{font:inherit;padding:7px;border:1px solid #8396a3;border-radius:5px;background:white}button{cursor:pointer;color:#005c6d}button:focus,select:focus{outline:3px solid #edb64c}canvas{display:block;width:100%;max-width:512px;image-rendering:pixelated;border:1px solid #b7c9d2;cursor:crosshair}table{border-collapse:collapse;width:100%;font-size:.9rem}td,th{padding:8px;border-bottom:1px solid #dce4e9;text-align:right}td:first-child,th:first-child{text-align:left}th{background:#eef3f6;position:sticky;top:0;z-index:1}tr.selected{background:#e2f5f2}.scroll{max-height:460px;overflow:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.88rem}.token{font-family:monospace;white-space:pre-wrap}.muted{color:#526979}.positive{color:#9e3b23}.negative{color:#13685a}#excerpt{max-height:130px;overflow:auto;white-space:pre-wrap}.legend{height:10px;background:linear-gradient(to right,#f5faff,#12647d);max-width:512px}a{color:#005e83}@media(max-width:800px){.grid{grid-template-columns:1fr}body{padding:12px}.card{padding:15px}h1{font-size:1.8rem}}
</style>
<header><div class="eyebrow">ATTENTION INTERVENTION LAB / PRETRAINED CPU EXAMPLE</div><h1>Where a head looks. What its replacement changes.</h1>
<p>Pythia-14M on public literary text. Select a head, inspect its intact attention, and compare the measured next-token loss after replacing that head’s output with zero or a separately calibrated mean.</p></header>
<noscript>This interactive report requires JavaScript. The accompanying summary.json and measurements.npz contain the numerical results.</noscript>
<section class="card"><h2>Measured on 1,024 next-token predictions</h2><div class="metrics"><div class="metric">Intact loss (nats)<strong id="baseline"></strong></div><div class="metric">No-op maximum loss change<strong id="noop"></strong></div><div class="metric">Heads × replacement methods<strong>24 × 2</strong></div></div><p id="finding"></p><p class="muted">Positive Δ means worse prediction; negative Δ means improved prediction. Results describe 16 consecutive blocks from one book, not independent population samples. All heads are shown, including small and opposite-sign effects.</p></section>
<section class="card"><h2>Inspect one head and prediction</h2><div class="controls"><label>Head<select id="head"></select></label><label>Example block<select id="example"><option value="0">0 · first evaluation block</option><option value="1">1 · second evaluation block</option></select></label><label>Replacement<select id="method"><option value="zero">Zero ablation</option><option value="mean">Mean ablation</option></select></label><label>Query position<select id="query"></select></label></div>
<p id="selection" aria-live="polite"></p><div class="grid"><div><canvas id="heatmap" width="512" height="512" role="img" aria-label="Intact attention heatmap: query rows, key columns; equivalent values in attention table"></canvas><div class="legend"></div><p class="muted">Attention weight: 0 (pale) → 1 (dark). Rows are query positions; columns are key positions, both 0–63. Click a row to inspect it. Future positions are masked. Outlined row is selected.</p><p id="hover" class="token"></p></div><div><h3>Prediction and intervention</h3><p id="prediction" class="token"></p><div id="effect" aria-live="polite"></div><p id="aggregate"></p><p class="muted">The intact heatmap stays fixed when switching replacements. Ablation replaces the selected head’s attention-weighted value vector at every position, before the output projection; it does not erase attention edges. Loss is scored on the actual next token.</p><details><summary>Evaluation text in this block</summary><p id="excerpt"></p></details><h3>Selected query’s attention</h3><div class="scroll"><table><thead><tr><th>Key / token</th><th>Weight</th></tr></thead><tbody id="weights"></tbody></table></div></div></div></section>
<section class="card"><h2>Every head, same evaluation inputs</h2><p>Click a head to link its aggregate effect to the visualization. Block ranges show variability, not confidence intervals. “Harmed” counts blocks whose average loss increased.</p><div class="scroll"><table><thead><tr><th>Head</th><th>Zero Δ nats</th><th>Mean Δ nats</th><th>Mean − zero</th><th>Zero harmed / 16</th><th>Mean harmed / 16</th></tr></thead><tbody id="allheads"></tbody></table></div></section>
<section class="card"><h2>What this does and does not establish</h2><p>These are causal effects of specified replacements on this model and these inputs. Attention weights alone do not include the value vectors or downstream computation. A large effect does not identify a complete head function, and a small effect does not prove irrelevance. Zero and mean replacements can create atypical hidden states; disagreement between them is substantive evidence about intervention sensitivity.</p><p>Calibration uses 1,024 input positions from <em>Alice’s Adventures in Wonderland</em>; evaluation uses 1,024 predictions from <em>The Adventures of Sherlock Holmes</em>. Each split has 16 non-overlapping 65-token blocks: 64 inputs plus the final target. Context resets between blocks, with no added BOS token. Means pool all calibration positions and remain fixed. This small pretrained checkpoint may have seen both books during training. The texts are separate here, not demonstrated unseen training data. No general language-model, task-generalization or statistical-significance claim follows.</p><p>Only the first two evaluation blocks have saved attention visualizations, chosen before measurement. Aggregate loss covers all 16 blocks. Displayed attention is rounded to six decimals; the NPZ preserves float32 values. Float32 CPU eager attention, dropout disabled, two threads, no KV cache. No-op uses the same cloning/reassignment path and must exactly preserve every token loss for every head.</p></section>
<section class="card"><h2>Reproduce and inspect</h2><p>Open this HTML directly; it needs no server or network. From the repository root, after the documented dependency setup:</p><pre>.venv/bin/python -m attention_lab.pretrained fetch
.venv/bin/python -m attention_lab.pretrained run --output /tmp/attention-pretrained-replay
.venv/bin/python scripts/verify_pretrained.py --replay /tmp/attention-pretrained-replay</pre><p>The first command downloads and verifies the pinned public model once. The second runs fully offline. Model weights are cached outside the tracked tree. Exact inputs, excerpts, source hashes and protocol are in <code>experiments/pretrained</code>; per-token losses, calibration means, full-precision attention and provenance accompany this report.</p><p><a href="https://huggingface.co/EleutherAI/pythia-14m">Model card</a> · <a href="https://www.gutenberg.org/ebooks/11">Calibration source</a> · <a href="https://www.gutenberg.org/ebooks/1661">Evaluation source</a> · <a href="https://github.com/jessevig/bertviz">BertViz: related visualization work</a></p><details><summary>Exact model and execution provenance</summary><pre id="provenance"></pre></details></section>
<script id="data" type="application/json">__DATA__</script><script>
'use strict';const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),fmt=x=>Number(x).toFixed(6),signed=x=>(x>=0?'+':'')+fmt(x);let current;
function td(row,text,tag='td'){const cell=document.createElement(tag);cell.textContent=text;row.appendChild(cell);return cell}
$('baseline').textContent=fmt(D.summary.intact_loss_nats);$('noop').textContent=fmt(D.summary.noop_max_abs_token_loss_delta);
const zero=D.summary.heads.filter(h=>h.zero.delta_nats<0).length,mean=D.summary.heads.filter(h=>h.mean.delta_nats<0).length,opposite=D.summary.heads.filter(h=>h.zero.delta_nats*h.mean.delta_nats<0).length;
$('finding').textContent=`Replacing a head improved average loss for ${zero}/24 zero ablations and ${mean}/24 mean ablations. The two methods disagree in sign for ${opposite}/24 heads. These descriptive counts include arbitrarily small changes; they are not significance tests.`;
D.summary.heads.forEach((h,i)=>{const option=document.createElement('option');option.value=i;option.textContent=`L${h.layer}H${h.head}`;$('head').appendChild(option);const row=document.createElement('tr');row.dataset.head=i;const cell=td(row,'');const button=document.createElement('button');button.textContent=option.textContent;button.onclick=()=>{$('head').value=i;update();$('head').focus()};cell.appendChild(button);td(row,signed(h.zero.delta_nats));td(row,signed(h.mean.delta_nats));td(row,signed(h.mean_minus_zero_nats));td(row,h.zero.harmed_blocks);td(row,h.mean.harmed_blocks);$('allheads').appendChild(row)});
for(let q=0;q<64;q++){const option=document.createElement('option');option.value=q;option.textContent=q;$('query').appendChild(option)}$('query').value=31;
function update(){const i=+$('head').value,e=+$('example').value,q=+$('query').value,m=$('method').value,h=D.summary.heads[i],a=D.attention[e][h.layer][h.head],b=D.intact[e][q],v=D[m][h.layer][h.head][e][q];current={e,q,a};$('selection').textContent=`L${h.layer}H${h.head} · block ${e} · query ${q} · ${m} replacement`;$('prediction').textContent=`Query ${q}: ${JSON.stringify(D.examples[e].tokens[q])}\nTarget ${q+1}: ${JSON.stringify(D.examples[e].tokens[q+1])}`;$('effect').textContent=`Token loss: intact ${fmt(b)} → ${m} ${fmt(v)} nats; Δ ${signed(v-b)}.`;$('aggregate').textContent=`All 16 blocks, this head: Δ ${signed(h[m].delta_nats)} nats/token; block range [${signed(h[m].min_block_delta)}, ${signed(h[m].max_block_delta)}]. ${h[m].harmed_blocks}/16 blocks harmed, ${h[m].improved_blocks}/16 improved.`;$('excerpt').textContent=D.examples[e].text;$('weights').replaceChildren();a[q].forEach((weight,k)=>{const row=document.createElement('tr');td(row,`${k}: ${JSON.stringify(D.examples[e].tokens[k])}`);td(row,fmt(weight));$('weights').appendChild(row)});const ctx=$('heatmap').getContext('2d');for(let y=0;y<64;y++)for(let x=0;x<64;x++){let w=a[y][x];ctx.fillStyle=`rgb(${245-227*w},${250-150*w},${255-130*w})`;ctx.fillRect(x*8,y*8,8,8)}ctx.strokeStyle='#c27400';ctx.lineWidth=2;ctx.strokeRect(1,q*8+1,510,6);document.querySelectorAll('#allheads tr').forEach(row=>row.classList.toggle('selected',+row.dataset.head===i));$('hover').textContent='';}
for(const id of ['head','example','method','query'])$(id).addEventListener('change',update);
$('heatmap').onclick=event=>{const r=event.currentTarget.getBoundingClientRect();$('query').value=Math.min(63,Math.max(0,Math.floor((event.clientY-r.top)/r.height*64)));update()};
$('heatmap').onmousemove=event=>{const r=event.currentTarget.getBoundingClientRect(),q=Math.min(63,Math.max(0,Math.floor((event.clientY-r.top)/r.height*64))),k=Math.min(63,Math.max(0,Math.floor((event.clientX-r.left)/r.width*64)));$('hover').textContent=`Query ${q} → key ${k} ${JSON.stringify(D.examples[current.e].tokens[k])}: ${fmt(current.a[q][k])}`};
$('provenance').textContent=JSON.stringify(D.provenance,null,2);update();
</script></html>'''
